local PetSystem = require("client.slua.logic.pet.logic_pet")
local UI_Pet_Share = {}

local util = require("ui.util")
local sound = require("client.slua.config.sound")
local ui_manager = require("ui.manager")
local ImageDownloader = import("ImageDownloader")

local C_DownLoad_Try_Max_Count = 3

function UI_Pet_Share:ctor()
    self.nCurPetID = 0
    self.sBgUrl = ""
    self.downloader = nil
    self.downloadTryCount = 0
end

function UI_Pet_Share:OnInitialize()
    UI_Pet_Share.__super.OnInitialize(self)
end

function UI_Pet_Share:RegistEvents()
    UI_Pet_Share.__super.RegistEvents(self)

    self:AddOnClickedEvent("Button_0", self.CloseUI, self);
    self:AddOnClickedEvent("Button_OK", self.OnShare, self);
end

function UI_Pet_Share:UnRegistEvents()
    if self.downloader then
        self.downloader.OnSuccess:Clear()
        self.downloader.OnFail:Clear()
    end

    UI_Pet_Share.__super.UnRegistEvents(self)
end

function UI_Pet_Share:OnPostInitialize()
    UI_Pet_Share.__super.OnPostInitialize(self)

    --todo: OnPostInitialize在OnInitialize、RegistEvents之后，有需要在RegistEvents后初始化的工作写这里
end

