--界面显示时触发
function UI_Pet_Share:OnShow()

end

--界面隐藏时触发
function UI_Pet_Share:OnHide()

end

function UI_Pet_Share:Close()
    --todo: 这里做些消耗回收动作，注意UI_Pet_Share.__super.Close(self)一定要写在最后，遵循先进后出原则

    UI_Pet_Share.__super.Close(self)
end

function UI_Pet_Share:CloseUI()
    util.PlayAudio(sound.close, self.UIRoot)

    if ui_manager then
        ui_manager.CloseUI(ui_manager.UI_Config.pet_share)
    end
end

function UI_Pet_Share:SetData(petID)
    self.nCurPetID = petID

    self:InitUI()
end

function UI_Pet_Share:InitUI()
    local petID = self.nCurPetID
    local isOwned = PetSystem.HasPet(petID)
    local cfg = PetSystem.GetPetItemCfgByPetID(petID)

    if isOwned then
        self.UIRoot.CanvasPanel_tips:SetVisibility(UEnums.ESlateVisibility.Collapsed)
    else
        self.UIRoot.CanvasPanel_tips:SetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
    end
    self.UIRoot.Button_OK:SetIsEnabled(isOwned)

    self.sBgUrl = cfg.ShareBgUrl .. tostring(petID) .. "_" .. Client.GetCurrentLanguage() .. ".jpg"

    self.downloader = ImageDownloader.MakeDownLoader()
    local texture = self.downloader:GetTextureFromUrlWithoutDownload(self.sBgUrl)
    if texture then
        self.UIRoot.Image_14:SetBrushFromTexture(texture, false)
    else
        self.downloader.OnSuccess:Add(function()
            self:OnDownloadBgSuccess()
        end)
        self.downloader.OnFail:Add(function()
            self:OnDownloadBgFail()
        end)
        self.downloader:Start(self.sBgUrl)
    end
end

function UI_Pet_Share:OnDownloadBgSuccess()
    log("[edward][pet_share] OnDownloadBgSuccess");
    local downloader = ImageDownloader.MakeDownLoader()
    local texture = downloader:GetTextureFromUrlWithoutDownload(self.sBgUrl)
    if texture then
        self.UIRoot.Image_14:SetBrushFromTexture(texture, false)
    end
end

function UI_Pet_Share:OnDownloadBgFail()
    log("[edward][pet_share] OnDownloadBgFail");
    if self.downloadTryCount >= C_DownLoad_Try_Max_Count then
        return
    end

    self.downloadTryCount = self.downloadTryCount + 1
    self.downloader:Start(self.sBgUrl)
end

function UI_Pet_Share:OnShare()
    util.PlayAudio(sound.click, self.UIRoot)

    local isOwned = PetSystem.HasPet(self.nCurPetID)
    if not isOwned then
        return
    end

    if ui_manager then
        local uiConfig = ui_manager.UI_Config.pet_share_choose
        ui_manager.ShowUI(uiConfig)
        ui_manager.GetUI(uiConfig):SetData(self.sBgUrl)
    end

    self:CloseUI()
end

local class = require("class")
local ui_base = require("ui.base")
local CUIPet_Share = class(ui_base, nil, UI_Pet_Share)

return CUIPet_Share